#include "src/host_sbs_temporal_source_ledger.h"
#include <gtest/gtest.h>
namespace {
using namespace models::host_sbs_temporal_source_bridge;
domain_t domain(){domain_t d;d.source_width=1920;d.source_height=1080;d.analysis_ltrb={0,0,1920,1080};d.context_generation=5;return d;}
observation_t input(std::uint64_t clock,std::uint64_t token,bool adjacent=true){observation_t x;x.domain=domain();x.source_epoch=7;x.capture_clock_us=clock;x.content_clock_us=clock;x.history_identity=9;x.surface_token=token;x.genuine_capture=true;x.immediate_previous_capture_observed=adjacent;return x;}
TEST(HostSbsTemporalSourceLedger, RetryCannotUpgradeFirstUnknownTransition){ledger_t l;ASSERT_TRUE(l.begin_domain(7,domain()));auto a=l.observe(input(10,1));auto b=l.observe(input(20,3,false));ASSERT_TRUE(a.valid());ASSERT_TRUE(b.valid());EXPECT_FALSE(b.predecessor_contiguous);auto retry=l.observe(input(20,3,true));EXPECT_EQ(retry.material_serial,b.material_serial);EXPECT_EQ(retry.capture_clock_us,b.capture_clock_us);EXPECT_FALSE(retry.predecessor_contiguous);}
TEST(HostSbsTemporalSourceLedger, ModelIdentifiersDoNotEnterMaterialClock){ledger_t l;ASSERT_TRUE(l.begin_domain(7,domain()));auto a=l.observe(input(10,1));EXPECT_EQ(a.material_serial,1u);auto retry=l.observe(input(10,1));EXPECT_EQ(retry.material_serial,1u);auto b=l.observe(input(20,2));EXPECT_EQ(b.material_serial,2u);EXPECT_EQ(b.capture_clock_us,20u);EXPECT_TRUE(b.predecessor_contiguous);}
TEST(HostSbsTemporalSourceLedger, ChangedUnmodelledCaptureCannotBeCompressed){ledger_t l;ASSERT_TRUE(l.begin_domain(7,domain()));auto a=l.observe(input(10,1));ASSERT_TRUE(l.note_admitted(a));l.observe(input(20,2));auto d=l.observe(input(30,3));EXPECT_EQ(d.material_serial,3u);EXPECT_TRUE(d.predecessor_contiguous);EXPECT_EQ(l.counters().admitted,1u);}
TEST(HostSbsTemporalSourceLedger, OnlyAdjacentProvedCleanCaptureFolds){ledger_t l;ASSERT_TRUE(l.begin_domain(7,domain()));auto a=l.observe(input(10,1));auto clean=input(20,2);clean.exact_analysis_pixels_unchanged=true;auto b=l.observe(clean);EXPECT_EQ(b.material_serial,a.material_serial);EXPECT_EQ(b.capture_clock_us,a.capture_clock_us);EXPECT_FALSE(b.predecessor_contiguous);auto gap=input(30,5,false);gap.exact_analysis_pixels_unchanged=true;auto c=l.observe(gap);EXPECT_EQ(c.material_serial,2u);EXPECT_FALSE(c.predecessor_contiguous);}
TEST(HostSbsTemporalSourceLedger, RegressionPoisonsNextTransitionWithoutRewind){ledger_t l;ASSERT_TRUE(l.begin_domain(7,domain()));l.observe(input(10,1));l.observe(input(20,2));EXPECT_FALSE(l.observe(input(15,3)).valid());auto c=l.observe(input(30,4));EXPECT_EQ(c.material_serial,3u);EXPECT_FALSE(c.predecessor_contiguous);}
TEST(HostSbsTemporalSourceLedger, SameStampConflictIsUnknown){ledger_t l;ASSERT_TRUE(l.begin_domain(7,domain()));l.observe(input(10,1));EXPECT_FALSE(l.observe(input(10,2)).valid());auto b=l.observe(input(20,3));EXPECT_FALSE(b.predecessor_contiguous);}
TEST(HostSbsTemporalSourceLedger, DomainRequiresExplicitNewEpoch){ledger_t l;ASSERT_TRUE(l.begin_domain(7,domain()));l.observe(input(10,1));auto x=input(20,2);x.domain.transfer=1;EXPECT_FALSE(l.observe(x).valid());EXPECT_FALSE(l.begin_domain(7,x.domain));ASSERT_TRUE(l.begin_domain(8,x.domain));x.source_epoch=8;auto a=l.observe(x);EXPECT_EQ(a.material_serial,1u);EXPECT_FALSE(a.predecessor_contiguous);}
TEST(HostSbsTemporalSourceLedger, MissingCaptureIsUnknownNeverSyntheticAge){ledger_t l;ASSERT_TRUE(l.begin_domain(7,domain()));auto x=input(10,1);x.genuine_capture=false;EXPECT_FALSE(l.observe(x).valid());x.genuine_capture=true;x.capture_clock_us=0;EXPECT_FALSE(l.observe(x).valid());}
TEST(HostSbsTemporalSourceLedger, UnknownIntervalRetryDoesNotClearGap){ledger_t l;ASSERT_TRUE(l.begin_domain(7,domain()));l.observe(input(10,1));l.uncertain_interval();EXPECT_FALSE(l.observe(input(10,1)).valid());auto b=l.observe(input(20,2));EXPECT_FALSE(b.predecessor_contiguous);auto c=l.observe(input(30,3));EXPECT_TRUE(c.predecessor_contiguous);}

}
